/* Phase 1: hero scroll animation. Phase 2: theme tokens, fonts and the wordmark. */

*,
*::before,
*::after {
  box-sizing: border-box;
}

/* Dark theme, from design-system/quran-landing/MASTER.md. The background is the footage's own #1F1A18
   rather than MASTER's #1C1917 (three shades apart), so the frame's edges disappear without a blend.
   Cinzel for the name and the bright gold were chosen by the user from on-page options. */
:root {
  --color-background: #1F1A18;
  --color-foreground: #FAFAF9;
  --color-muted-foreground: #A8A29E;
  --color-accent: #D4AF37;
  --font-display: Cinzel, 'Trajan Pro', Georgia, serif;
  --font-body: Jost, system-ui, sans-serif;
  color-scheme: dark;
}

html,
body {
  margin: 0;
  background: var(--color-background);
  color: var(--color-foreground);
  font-family: var(--font-body);
}

/* A tall section; the stage inside it stays pinned while it scrolls past. Its height sets
   how much scrolling the opening takes: slower on computers, where a mouse wheel moves in
   big steps, than on phones. */
.hero {
  position: relative;
  height: 550vh;
}

@media (max-width: 767px) {
  .hero {
    height: 400vh;
  }
}

.stage {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh; /* the book stays whole behind mobile browser bars */
  overflow: hidden;
}

.stage canvas {
  display: block;
  width: 100%;
  height: 100%;
}

/* The name, centred in the space under the closed book. --book-h is the book's height on screen,
   set by main.js, which also fades the name out as the cover starts to open. */
.wordmark {
  position: absolute;
  left: 0;
  right: 0;
  bottom: calc((50% - var(--book-h, 60svh) / 2) / 2);
  transform: translateY(50%);
  padding: 0 1.5rem;
  text-align: center;
}

.wordmark h1 {
  margin: 0;
  padding-left: 0.2em; /* balances the letter-spacing after the last letter, so the name sits truly centred */
  font-family: var(--font-display);
  font-size: clamp(1.125rem, 0.9rem + 1vw, 1.625rem);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--color-accent);
}

.wordmark p {
  margin: 0.7em 0 0;
  font-size: clamp(0.8125rem, 0.75rem + 0.3vw, 0.9375rem);
  font-weight: 300;
  letter-spacing: 0.06em;
  color: var(--color-muted-foreground);
}

/* Reduced motion: no scrubbing, just the open book. */
.still .hero {
  height: auto;
}

