1	// Phase 1: the hero scroll animation. Phase 2: the wordmark that sits with the closed book.
2	// Retouched video frames of the Qur'an opening, drawn to a canvas by scroll position.
3	// Spec: WEBSITE-BUILD.md sections 2 and 3; the settings the user chose are under section 7.
4	
5	(() => {
6	  const clamp = (v) => Math.min(1, Math.max(0, v));
7	
8	  // Frames --------------------------------------------------------------------
9	
10	  const SKIP = [39, 40]; // identical to f038, a hold in the source video
11	  const urls = [];
12	  for (let i = 0; i <= 88; i++) {
13	    if (!SKIP.includes(i)) urls.push(`assets/hero/frames/f${String(i).padStart(3, '0')}.png`);
14	  }
15	  const LAST = urls.length - 1; // 87 frames, indices 0..86
16	
17	  // Geometry, in pixels of the 1280x720 frames ----------------------------------
18	
19	  const SRC_W = 1280;
20	  const SRC_H = 720;
21	  const BOOK_LEFT = 255;   // left edge of the book; it never moves in the footage
22	  const BOOK_H = 580;      // y 70-650, centred on the frame's middle
23	  const SPINE = 640;       // right edge until the cover passes upright
24	  const OPEN_RIGHT = 1037; // right edge fully open
25	  const FEATHER_X = 180;   // how far the frame's rectangle fades into the stage
26	  const FEATHER_Y = 40;
27	
28	  // Timeline, as a share of the hero's scroll ------------------------------------
29	
30	  const OPEN_START = 0.1;
31	  const OPEN_END = 0.6;
32	  const NAME_GONE = 8; // the wordmark has faded out by this frame, early in the opening
33	
34	  // Smoothing ---------------------------------------------------------------------
35	
36	  // A mouse wheel scrolls in steps, so the book glides toward the scroll position instead of
37	  // jumping to it, cross-fading between frames. The user chose this "slow glide" by eye.
38	  const GLIDE = 0.28; // roughly the seconds it takes to close two thirds of the gap
39	
40	  const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)');
41	  const hero = document.querySelector('.hero');
42	  const stage = hero.querySelector('.stage');
43	  const canvas = stage.querySelector('canvas');
44	  const wordmark = stage.querySelector('.wordmark');
45	  const ctx = canvas.getContext('2d');
46	
47	  const frames = []; // decoded images by index, filled in as they arrive
48	  const rights = []; // measured right edge of the book in each frame
49	  const started = new Set();
50	
51	  let scale = 1;    // footage pixels to CSS pixels, set on resize
52	  let pos = null;   // frame position on screen; fractional while gliding or between frames
53	  let drawn = null; // position last drawn
54	  let last = 0;     // time of the previous glide step, 0 when the book is at rest
55	  let dirty = true;
56	  let queued = false;
57	  let visible = true;
58	
59	  // Loading -----------------------------------------------------------------------
60	
61	  function load(i) {
62	    if (started.has(i)) return;
63	    started.add(i);
64	    const img = new Image();
65	    img.src = urls[i];
66	    img.decode().then(
67	      () => {
68	        frames[i] = img;
69	        rights[i] = measureRight(img);
70	        dirty = true;
71	        schedule();
72	      },
73	      () => console.warn(`Frame missing: ${urls[i]}`), // the nearest loaded frame is drawn instead
74	    );
75	  }
76	
77	  // First and last frames, then coarse to fine, so scrubbing works before everything arrives.
78	  function loadAll() {
79	    load(0);
80	    load(LAST);
81	    for (const step of [8, 4, 2, 1]) {
82	      for (let i = 0; i <= LAST; i += step) load(i);
83	    }
84	  }
85	
86	  // Once the cover passes upright its cream lining faces the camera, so the book's right
87	  // edge is the rightmost bright pixel along the middle row, and never less than the spine.
88	  const probe = document.createElement('canvas');
89	  probe.width = SRC_W;
90	  probe.height = 1;
91	  const probeCtx = probe.getContext('2d', { willReadFrequently: true });
92	
93	  function measureRight(img) {
94	    try {
95	      probeCtx.drawImage(img, 0, SRC_H / 2, SRC_W, 1, 0, 0, SRC_W, 1);
96	      const px = probeCtx.getImageData(0, 0, SRC_W, 1).data;
97	      for (let x = SRC_W - 1; x > SPINE; x--) {
98	        if (px[x * 4] + px[x * 4 + 1] + px[x * 4 + 2] > 300) return x + 1;
99	      }
100	      return SPINE;
101	    } catch {
102	      return null; // pixels unreadable, e.g. opened as a file rather than through serve.js
103	    }
104	  }
105	
106	  // Averaged over nearby frames so the centring glides instead of stepping.
107	  function rightEdge(i) {
108	    let sum = 0;
109	    let n = 0;
110	    for (let j = Math.max(0, i - 3); j <= Math.min(LAST, i + 3); j++) {
111	      if (rights[j] != null) {
112	        sum += rights[j];
113	        n++;
114	      }
115	    }
116	    return n ? sum / n : SPINE + ((OPEN_RIGHT - SPINE) * i) / LAST;
117	  }
118	
119	  // Drawing -----------------------------------------------------------------------
120	
121	  // Cross-fades the two frames either side of a position, or while they are still loading, draws
122	  // the nearest frame that has arrived. Returns false while no frame has loaded yet.
123	  function draw(at) {
124	    const a = Math.floor(at);
125	    const b = Math.min(a + 1, LAST);
126	    const f = at - a;
127	    const fade = f > 0 && !!frames[a] && !!frames[b];
128	    const base = fade ? a : nearestLoaded(Math.round(at));
129	    if (base < 0) return false;
130	
131	    const width = canvas.clientWidth;
132	    const height = canvas.clientHeight;
133	    // The book is centred by choosing which part of the frame is drawn, never by moving the canvas.
134	    const centre = (BOOK_LEFT + rightEdge(a) + (rightEdge(b) - rightEdge(a)) * f) / 2;
135	    const w = SRC_W * scale;
136	    const h = SRC_H * scale;
137	    const x = width / 2 - centre * scale;
138	    const y = (height - h) / 2;
139	
140	    ctx.globalCompositeOperation = 'source-over';
141	    ctx.clearRect(0, 0, width, height);
142	    ctx.drawImage(frames[base], x, y, w, h);
143	    if (fade) {
144	      ctx.globalAlpha = f;
145	      ctx.drawImage(frames[b], x, y, w, h);
146	      ctx.globalAlpha = 1;
147	    }
148	
149	    // Fade the frame's rectangle out at its edges so it never shows against the stage.
150	    ctx.globalCompositeOperation = 'destination-in';
151	    ctx.fillStyle = feather(ctx.createLinearGradient(x, 0, x + w, 0), FEATHER_X / SRC_W);
152	    ctx.fillRect(x, y, w, h);
153	    ctx.fillStyle = feather(ctx.createLinearGradient(0, y, 0, y + h), FEATHER_Y / SRC_H);
154	    ctx.fillRect(x, y, w, h);
155	    ctx.globalCompositeOperation = 'source-over';
156	    return true;
157	  }
158	
159	  function feather(gradient, edge) {
160	    gradient.addColorStop(0, 'rgba(0, 0, 0, 0)');
161	    gradient.addColorStop(edge, '#000');
162	    gradient.addColorStop(1 - edge, '#000');
163	    gradient.addColorStop(1, 'rgba(0, 0, 0, 0)');
164	    return gradient;
165	  }
166	
167	  // Where the scroll says the book should be, in frames (fractional).
168	  function targetPos() {
169	    if (reduceMotion.matches) return LAST;
170	    const range = hero.offsetHeight - stage.offsetHeight;
171	    const p = range > 0 ? clamp(-hero.getBoundingClientRect().top / range) : 0;
172	    const t = clamp((p - OPEN_START) / (OPEN_END - OPEN_START));
173	    return t * t * (3 - 2 * t) * LAST; // smoothstep: eases into and out of the opening
174	  }
175	
176	  function nearestLoaded(i) {
177	    for (let d = 0; d <= LAST; d++) {
178	      if (frames[i - d]) return i - d;
179	      if (frames[i + d]) return i + d;
180	    }
181	    return -1;
182	  }
183	
184	  function schedule() {
185	    if (queued) return;
186	    queued = true;
187	    requestAnimationFrame(step);
188	  }
189	
190	  // Each animation frame, moves the book part of the way toward the scroll position and keeps
191	  // going until it arrives. Uses elapsed time, so it feels the same on 60 Hz and 144 Hz screens.
192	  function step(now) {
193	    queued = false;
194	    if (!visible) {
195	      last = 0;
196	      return;
197	    }
198	    const target = targetPos();
199	    if (pos === null || reduceMotion.matches) {
200	      pos = target;
201	    } else {
202	      const dt = last ? Math.min(now - last, 50) / 1000 : 1 / 60;
203	      pos += (target - pos) * (1 - Math.exp(-dt / GLIDE));
204	      if (Math.abs(target - pos) < 0.01) pos = target;
205	    }
206	    last = pos === target ? 0 : now;
207	    paint();
208	    if (pos !== target) schedule();
209	  }
210	
211	  // Redraws only when the position, size, loaded frames or a setting have changed.
212	  function paint() {
213	    if (pos === null || (pos === drawn && !dirty)) return;
214	    // The name belongs to the closed book, so it fades as the cover lifts. Under reduced motion
215	    // the book is shown open, and the name stays.
216	    wordmark.style.opacity = reduceMotion.matches ? 1 : 1 - clamp(pos / NAME_GONE);
217	    if (draw(pos)) {
218	      drawn = pos;
219	      dirty = false;
220	    }
221	  }
222	
223	  function resize() {
224	    const width = canvas.clientWidth;
225	    const height = canvas.clientHeight;
226	    const dpr = Math.min(devicePixelRatio || 1, 2);
227	    canvas.width = Math.round(width * dpr);
228	    canvas.height = Math.round(height * dpr);
229	    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
230	    ctx.imageSmoothingQuality = 'high';
231	    // One size for the whole opening: the open book always fits, and the 720p footage is
232	    // never stretched past its own size.
233	    scale = Math.min((height * 0.8) / BOOK_H, (width * 0.88) / (OPEN_RIGHT - BOOK_LEFT), 1);
234	    stage.style.setProperty('--book-h', `${BOOK_H * scale}px`); // lets CSS place the name beside the book
235	    dirty = true;
236	    paint(); // draw now: resizing the canvas has just cleared it
237	    schedule(); // the hero's height follows the window, so the scroll position may now mean a different frame
238	  }
239	
240	  // Reduced motion: no scrubbing, just the open book, and only its frame is loaded.
241	  function applyMotion() {
242	    document.documentElement.classList.toggle('still', reduceMotion.matches);
243	    if (reduceMotion.matches) load(LAST);
244	    else loadAll();
245	    dirty = true;
246	    schedule();
247	  }
248	
249	  addEventListener('scroll', schedule, { passive: true });
250	  reduceMotion.addEventListener('change', applyMotion);
251	  new ResizeObserver(resize).observe(canvas);
252	  new IntersectionObserver(([entry]) => {
253	    visible = entry.isIntersecting;
254	    dirty = true;
255	    schedule();
256	  }).observe(hero);
257	  applyMotion();
258	})();
259

